package run.ikaros.sharing; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2") public class InviteController{private final InviteService service;public InviteController(InviteService s){service=s;}@PostMapping("/rooms/{roomId}/invites")public Mono<InviteView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID roomId,@Valid@RequestBody CreateInviteRequest r){return service.create(a,roomId,r);}@GetMapping("/invites")public Flux<InviteView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a){return service.list(a);}@PostMapping("/invites/{id}/actions/accept")public Mono<InviteView> accept(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.accept(a,id);}@PostMapping("/invites/{id}/actions/decline")public Mono<InviteView> decline(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.decline(a,id);}@PostMapping("/invites/{id}/actions/revoke")public Mono<InviteView> revoke(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.revoke(a,id);}}
